	}
lzs=source.getVariable()?source.getVariable():'';
lzb=book.getVariable("custom")?book.getVariable("custom"):'';
html=result.replace(/<\/td>\s*(<a|<strong|<img)/g,'</td>◎◎◎◎$1');
html=html
.replace(/<td (class="t_f"[\s\S]+?)<\/td>/g,'<li $1</li>')
.replace(/<i.*?<\/i><br>/g,'');
list=html.split("◎◎◎◎");
h="";


durChapterIndex = book.durChapterIndex;
lastChapterNum = book.totalChapterNum-1;


function saveLength(t){
	let re;
	re = new RegExp("\\s*这是"+t+"的楼层数量：\\d+","g");
	lzb = String(lzb).replace(re,"\n这是"+t+"的楼层数量："+list.length);
book.putCustomVariable(lzb)
	}

if(durChapterIndex===lastChapterNum){
	saveLength(title)
}

if(durChapterIndex===(lastChapterNum-1)){
saveLength(title)
}

lzb = processPageLines(lzb);
book.putCustomVariable(lzb);

for(i in list){

	java.setContent(list[i]);	author=java.getString("@@class.xi2@text")!=""?java.getString("@@class.xi2@text"):"匿名青花鱼";
time=java.getString("@@tag.em.-1@text");
bName=java.getString("@@blockquote@tag.font.0@text")+"\n";
lc = "•"+String(java.getString("@@tag.strong@a@text")).replace(/条鱼/,'L');
reply=String(author).replace(/发表于.*/,'');
bName=String(bName).indexOf(reply)>-1?"":bName;
bText=java.getString("@@blockquote@textNodes||blockquote@tag.font.-1@textNodes")
bText=bText!=""?"回复:『"+bName+bText+"』":"";
lz=(book.author == author)?"👤":"📜";
j=org.jsoup.Jsoup.parse(list[i]);

	j.select("blockquote").remove();
	tt=j.select(".t_f,.typeoption").html(); 
	if(lzs.indexOf("保留")>-1||lzb.indexOf("保留")>-1){
		if(/👤/.test(lz)){
			   h+=lz+author+time+lc+"\n"+"\n"+bText+tt+"\n&lrm;\n"  	
			}  
		}else if(lzs.indexOf("只看楼主")>-1||lzb.indexOf("只看楼主")>-1){
		if(/👤/.test(lz)){
			   h+=tt;
			} 

		}else{
				h+=lz+author+time+lc+"\n"+"\n"+bText+tt+"\n&lrm;\n"  	
			}
	}
h
